import { useSyncExternalStore } from 'react';
import { registerSW } from 'virtual:pwa-register';

/**
 * The app's only service-worker registration (generated by vite-plugin-pwa, see vite.config.ts).
 *
 * The worker precaches the app shell and static assets. It never caches API
 * responses, so patient histories, predictions, alerts and live events are
 * always fetched live and fail visibly when offline.
 *
 * Update flow: a new worker installs in the background and WAITS. The user is
 * asked before it takes over (applyUpdate), so a running page is never swapped
 * mid-task. The page reloads once the new worker activates.
 */
export interface PwaState {
  needRefresh: boolean;
  offlineReady: boolean;
  registered: boolean;
  error: string | null;
}

const UPDATE_CHECK_MS = 60 * 60 * 1000;
let state: PwaState = { needRefresh: false, offlineReady: false, registered: false, error: null };
const listeners = new Set<() => void>();
let updateServiceWorker: ((reloadPage?: boolean) => Promise<void>) | null = null;
let initialized = false;

function setState(patch: Partial<PwaState>) {
  state = { ...state, ...patch };
  listeners.forEach((listener) => listener());
}

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Register the service worker once. Safe to call repeatedly; later calls are ignored. */
export function initPwa(): boolean {
  if (initialized || typeof window === 'undefined' || !('serviceWorker' in navigator)) return false;
  initialized = true;
  // Notification clicks route an already-open window in place (see public/push-sw.js).
  navigator.serviceWorker.addEventListener?.('message', (event: MessageEvent) => {
    const url = event.data?.type === 'vg-navigate' ? event.data.url : null;
    if (typeof url === 'string' && /^\/#\/[A-Za-z0-9/?=&_-]*$/.test(url)) window.location.hash = url.slice(2);
  });
  updateServiceWorker = registerSW({
    immediate: true,
    onNeedRefresh: () => setState({ needRefresh: true }),
    onOfflineReady: () => setState({ offlineReady: true }),
    onRegisteredSW: (_url, registration) => {
      setState({ registered: true });
      if (!registration) return;
      const check = () => { if (navigator.onLine) void registration.update().catch(() => undefined); };
      window.setInterval(check, UPDATE_CHECK_MS);
      document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') check(); });
    },
    onRegisterError: (error: unknown) => setState({ error: error instanceof Error ? error.message : 'Service worker registration failed' }),
  });
  return true;
}

/** User-confirmed: activate the waiting worker and reload into the new version. */
export async function applyUpdate(): Promise<void> {
  if (updateServiceWorker) await updateServiceWorker(true);
}

export function dismissUpdate() { setState({ needRefresh: false }); }
export function dismissOfflineReady() { setState({ offlineReady: false }); }

export function usePwaState(): PwaState {
  return useSyncExternalStore(subscribe, () => state, () => state);
}

/** Test-only reset of module state. */
export function __resetPwaForTests() {
  initialized = false;
  updateServiceWorker = null;
  state = { needRefresh: false, offlineReady: false, registered: false, error: null };
  listeners.clear();
}

function subscribeOnline(listener: () => void) {
  window.addEventListener('online', listener);
  window.addEventListener('offline', listener);
  return () => {
    window.removeEventListener('online', listener);
    window.removeEventListener('offline', listener);
  };
}

/** Browser connectivity. `true` does not guarantee the API is reachable; the live-channel status covers that. */
export function useOnlineStatus(): boolean {
  return useSyncExternalStore(subscribeOnline, () => navigator.onLine, () => true);
}
